def runs_dir(*sub):
    """运行产物目录（绝对路径）。子目录：daily / picks / runs / downloads / state。"""
    if _RUNS_OVERRIDE:
        return os.path.join(_RUNS_OVERRIDE, *sub) if sub else _RUNS_OVERRIDE
