def load_automation():
    try:
        cfg = K.load_lit_config()
    except Exception as e:                                     # noqa: BLE001
        print(f"[warn] 配置读取失败（{e}），使用内置默认方向", file=sys.stderr)
        cfg = {}
    a = (cfg.get("automation") or {})
    dirs = a.get("directions") or []
    if not dirs:
        print("[note] lit_config.yaml 没有 automation.directions，暂用内置默认方向"
              "（建议把方向搬进配置，改方向就不必碰脚本）", file=sys.stderr)
        dirs = DEFAULT_DIRECTIONS
    return {
        "window": a.get("window") or "近一周",
        "limit": int(a.get("limit") or 15),
        "results_dir": a.get("results_dir") or "",
        "directions": dirs,
    }


def load_json(path, default):
    try:
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    except Exception:                                          # noqa: BLE001
        return default


def save_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    os.replace(tmp, path)          # 原子替换：被外部杀掉也不会留下半截 JSON


class Tee:
    """同时写控制台与日志文件（无人值守时控制台可能根本不存在）。"""

    def __init__(self, path):
        self.f = None
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            self.f = open(path, "a", encoding="utf-8", newline="\n")
        except OSError:
            self.f = None

    def write(self, s):
        try:
            sys.stderr.write(s)
        except Exception:                                      # noqa: BLE001
            pass
        if self.f:
            try:
                self.f.write(s)
                self.f.flush()
            except Exception:                                  # noqa: BLE001
                pass

    def close(self):
        if self.f:
            self.f.close()


def run_discover(d, window, out_json, manifest, limit):
    cmd = [sys.executable, DISCOVER, d["query"], window,
           "--limit", str(limit), "--out", out_json, "--manifest", manifest]
    env = dict(os.environ, PYTHONIOENCODING="utf-8")
    t0 = time.time()
    try:
        r = subprocess.run(cmd, cwd=K.VAULT, env=env, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=900)
        rc, out = r.returncode, (r.stdout or "") + (r.stderr or "")
    except subprocess.TimeoutExpired:
        rc, out = 124, "子进程超时（900s）"
    tail = [ln.strip() for ln in out.splitlines() if ln.strip()][-2:]
    return rc, tail, round(time.time() - t0, 1)


def render_digest(day, quiet=False):
    """渲染交给 lit_digest.py（单一实现，避免两处格式漂移）。"""
    if not os.path.exists(DIGEST):
        return 1, "lit_digest.py 不存在"
    env = dict(os.environ, PYTHONIOENCODING="utf-8")
    r = subprocess.run([sys.executable, DIGEST, "--render", "--day", day],
                       cwd=K.VAULT, env=env, capture_output=True, text=True,
                       encoding="utf-8", errors="replace", timeout=300)
    return r.returncode, ((r.stdout or "") + (r.stderr or "")).strip()


def selftest():
    print("=== lit_daily --selftest ===")
    ok = fail = 0

    def chk(name, cond, extra=""):
        nonlocal ok, fail
        if cond:
            print(f"  [ok  ] {name}")
            ok += 1
        else:
            print(f"  [FAIL] {name} {extra}")
            fail += 1

    import shutil
    import tempfile
    # ⚠️ 自检的临时目录**不能落在库根**（旧版写 `<cwd>/_litwatch-selftest-daily`，
    #    在库根执行时会在知识库里留垃圾，还会被 kb_toolcheck 的写盘防呆判成"意外写盘"）。
    #    逐级回退：temp → cwd → 工具目录（tempfile.mkdtemp(dir=…) 在受限环境下
    #    可能"能建目录但不能写文件"，故不直接用 mkdtemp）。
    tmp = ""
    for base in (tempfile.gettempdir(), os.getcwd(), HERE):
        cand = os.path.join(base, "_litwatch-selftest-daily")
        try:
            shutil.rmtree(cand, ignore_errors=True)
            os.makedirs(cand, exist_ok=True)
            with open(os.path.join(cand, ".probe"), "w", encoding="utf-8") as f:
                f.write("x")
            os.remove(os.path.join(cand, ".probe"))
            tmp = cand
            break
        except OSError:
            continue
    if not tmp:
        print("  [FAIL] 无法创建自检临时目录")
        return 1
    g = globals()
    orig = (K.VAULT, g["_RUNS_OVERRIDE"])
    try:
        K.VAULT = tmp
        g["_RUNS_OVERRIDE"] = os.path.join(tmp, "lit-watch")
        os.makedirs(runs_dir("daily"), exist_ok=True)
        chk("默认方向兜底非空且含 slug/query",
            all(d.get("slug") and d.get("query") for d in DEFAULT_DIRECTIONS)
            and len(DEFAULT_DIRECTIONS) >= 4)
        chk("runs_dir 由 _RUNS_OVERRIDE 派生且带子目录",
            runs_dir("daily").endswith(os.path.join("lit-watch", "daily")))
        chk("产物目录不落在 _archive/ 下（2026-10-10 迁移纪律）",
            "_archive" not in runs_dir("daily").replace("\\", "/"))
        chk("load_json 损坏文件返回默认值",
            load_json(os.path.join(tmp, "nope.json"), {"a": 1}) == {"a": 1})
        p = os.path.join(tmp, "x.json")
        save_json(p, {"k": [1, 2]})
        chk("save_json 可读回（原子替换）", load_json(p, {}) == {"k": [1, 2]})
        chk("原子替换不留 .tmp", not os.path.exists(p + ".tmp"))
        log = os.path.join(tmp, "run.log")
        t = Tee(log)
        t.write("hello\n")
        t.close()
        chk("Tee 写日志文件", "hello" in open(log, encoding="utf-8").read())
    finally:
        K.VAULT = orig[0]
        g["_RUNS_OVERRIDE"] = orig[1]
        shutil.rmtree(tmp, ignore_errors=True)

    print(f"\n{'SELFTEST PASSED' if fail == 0 else 'SELFTEST FAILED'}: {ok}/{ok + fail}")
    return 0 if fail == 0 else 1


def main():
    ap = argparse.ArgumentParser(description="每日文献发现（配置驱动、可续跑、退出码可判）")
    ap.add_argument("--day", default="", help="日期目录（默认今天）")
    ap.add_argument("--window", default="", help="时间窗（默认取配置 automation.window）")
    ap.add_argument("--limit", type=int, default=0, help="每方向候选上限（0=取配置）")
    ap.add_argument("--directions", default="", help="只跑这些 slug（逗号分隔）")
    ap.add_argument("--resume", action="store_true", help="跳过今天已成功的方向")
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--no-render", action="store_true", help="跑完不重新渲染摘要")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    auto = load_automation()
    day = args.day or datetime.date.today().isoformat()
    window = args.window or auto["window"]
    limit = args.limit or auto["limit"]
    day_dir = runs_dir("daily", day)
    if not args.dry_run:
        os.makedirs(day_dir, exist_ok=True)   # 干跑不建目录：空目录是"当天任务被杀掉"的体检信号

    log = Tee(runs_dir("daily", f"run-{day}.log"))
    log.write(f"\n===== lit_daily {datetime.datetime.now():%Y-%m-%d %H:%M:%S} "
              f"day={day} window={window} =====\n")

    dirs = auto["directions"]
    if args.directions:
        want = {s.strip() for s in args.directions.split(",") if s.strip()}
        dirs = [d for d in dirs if d.get("slug") in want]
        if not dirs:
            log.write(f"[!] --directions 与配置里的方向都不匹配：{sorted(want)}\n")
            log.close()
            return 2

    prog_p = os.path.join(day_dir, "progress.json")
    prog = load_json(prog_p, {"day": day, "done": []})
    status = load_json(os.path.join(day_dir, "status.json"),
                       {"day": day, "window": window, "directions": []})
    by_slug = {d.get("slug"): d for d in status.get("directions") or []}

    for d in dirs:
        slug, label = d.get("slug"), d.get("label") or d.get("slug")
        if args.resume and slug in (prog.get("done") or []):
            log.write(f"[skip] {slug}：今天已完成（--resume）\n")
            continue
        out_json = os.path.join(day_dir, f"cand_{slug}.json")
        manifest = os.path.join(day_dir, f"manifest_{slug}.md")
        if args.dry_run:
            log.write(f"[dry] discover query={d.get('query')!r} window={window} "
                      f"limit={d.get('limit') or limit} -> {out_json}\n")
            continue
        log.write(f"[run ] {slug} ...\n")
        rc, tail, secs = run_discover(d, window, out_json, manifest,
                                      int(d.get("limit") or limit))
        n = 0
        if os.path.exists(out_json):
            n = len(load_json(out_json, {}).get("papers") or [])
        # 🔴 退出码语义：lit_discover 在**分片检索失败**时返回 3（本轮修好，此前只要
        #    有命中就返回 0）——那是"检索没跑完"，绝不能读成"这个方向没有新文献"，
        #    更不能让 --resume 当日永久跳过它。故 rc==3 记 ok=False + partial=True。
        rec = {"slug": slug, "label": label, "query": d.get("query"),
               "limit": int(d.get("limit") or limit), "ok": rc == 0, "count": n,
               "secs": secs, "partial": rc == 3,
               "error": "" if rc == 0 else f"rc={rc} " + " / ".join(tail)[:200]}

        # —— 立刻落盘：即使下一个方向被外部杀掉，这一轮的产物也是完整的 ——
        by_slug[slug] = rec
        order = [x.get("slug") for x in dirs]
        status["directions"] = [by_slug[s] for s in order if s in by_slug] + \
            [v for k, v in by_slug.items() if k not in order]
        status.update({"day": day, "window": window,
                       "updated": datetime.datetime.now().isoformat(timespec="seconds"),
                       "config": os.path.relpath(K.LIT_CONFIG_PATH, K.VAULT)})
        save_json(os.path.join(day_dir, "status.json"), status)
        if rc == 0:
            prog["done"] = sorted(set((prog.get("done") or []) + [slug]))
        save_json(prog_p, prog)
        if not args.no_render:
            rrc, rmsg = render_digest(day, quiet=True)
            rec["render_ok"] = rrc == 0
            if rrc != 0:
                log.write(f"[warn] 摘要渲染失败：{rmsg[-200:]}\n")
                # 渲染失败也要进 status.json——否则 status 说"全 ok"，
                # 而其实读者根本没有摘要可看（旧版只写日志）。
                status["directions"] = [by_slug[s] for s in order if s in by_slug] + \
                    [v for k, v in by_slug.items() if k not in order]
                save_json(os.path.join(day_dir, "status.json"), status)
        log.write(f"[{'ok  ' if rc == 0 else 'FAIL'}] {slug}: {n} 篇　{secs}s"
                  + (f"　{rec['error']}" if rec["error"] else "") + "\n")

    if args.dry_run:
        log.write("[dry] 结束（未执行任何检索）\n")
        log.close()
        return 0

    ok_n = sum(1 for r in status["directions"] if r.get("ok"))
    bad_n = sum(1 for r in status["directions"] if not r.get("ok"))
    partial_n = sum(1 for r in status["directions"] if r.get("partial"))
    total = sum(r.get("count") or 0 for r in status["directions"])
    log.write(f"[done] 方向 {len(status['directions'])}：成功 {ok_n} / 失败 {bad_n}"
              + (f"（其中分片失败 {partial_n}）" if partial_n else "")
              + f"；候选合计 {total} 篇\n")
    log.write(f"       摘要：{runs_dir('daily', 'latest-digest.md')}\n"
              f"       可点开副本：{os.path.join(auto['results_dir'], f'lit-watch-daily-{day}.md')}\n")
    run_log = runs_dir("daily", "run.log")
    try:
        with open(run_log, "a", encoding="utf-8", newline="\n") as f:
            f.write(f"{datetime.datetime.now().isoformat(timespec='seconds')}\t{total}篇\t"
                    f"{bad_n}方向失败\t{os.path.join(auto['results_dir'], f'lit-watch-daily-{day}.md')}\n")
    except OSError:
        pass
    log.close()

    if bad_n and ok_n == 0:
        return 4
    return 3 if bad_n else 0


if __name__ == "__main__":
    sys.exit(main())
